#pragma once
#include "room_rules_internal.hpp"
#include "../bigworld/stock_native_bot_combat.hpp"
namespace wot::room::rule {
namespace mechanics=wot::offline_bot_step;
inline mechanics::CombatState combat(const Value&actor){mechanics::CombatState s;s.health=static_cast<int>(intField(actor,"health"));s.maximum_health=static_cast<int>(intField(actor,"max_health",s.health));s.display_health=static_cast<int>(intField(actor,"display_health",s.health));s.alive=alive(actor);s.stun_end_server_time_ms=intField(actor,"stun_end_server_time_ms");const auto&raw=actor.get("critical");s.critical.crew_roster=strings(raw.get("crew_roster"));s.critical.crew_ko=strings(raw.get("crew_ko"));s.critical.fire=raw.get("fire").truth();s.critical.ammo_rack_death=raw.get("ammo_rack_death").truth();s.critical.fire_elapsed=actor.get("combat_fire_elapsed").numeric();s.critical.fire_timer=actor.get("combat_fire_timer").numeric();
 for(const auto&r:rows(raw.get("devices"))){auto&d=s.critical.devices[field(r,"name")];d.hp=r.get("hp").numeric();d.maximum=r.get("max_hp").numeric();d.wire_maximum=d.maximum;d.destroyed=field(r,"state")=="destroyed";d.critical=field(r,"state")=="critical";}
 for(const auto&r:rows(actor.get("effective_params").get("critical").get("devices"))){auto&d=s.critical.devices[field(r,"name")];d.maximum=r.get("max_hp").numeric();d.wire_maximum=d.maximum;if(has(r,"regen_hp"))d.regeneration=r.get("regen_hp").numeric();}if(s.critical.crew_roster.empty())s.critical.crew_roster=strings(actor.get("effective_params").get("critical").get("crew_roster"));return s;}
inline void restoreRoster(mechanics::CriticalState&state,const Value&actor){if(state.crew_roster.empty())state.crew_roster=strings(actor.get("critical").get("crew_roster"));if(state.crew_roster.empty())state.crew_roster=strings(actor.get("effective_params").get("critical").get("crew_roster"));}
inline Value critical(const mechanics::CriticalState&c){Value v=object(),ds=array();std::set<std::string> destroyed;for(const auto&kv:c.devices){const auto&d=kv.second;if(!d.hp)continue;Value row=object();row.object["name"]=text(kv.first);row.object["hp"]=number(rounded(*d.hp,3));row.object["max_hp"]=number(rounded(d.wire_maximum.value_or(d.maximum.value_or(1.)),3));row.object["state"]=text(d.destroyed?"destroyed":d.critical?"critical":"normal");ds.array.push_back(std::move(row));if(d.destroyed)destroyed.insert(kv.first);}v.object["devices"]=std::move(ds);v.object["destroyed"]=strings(destroyed);v.object["crew_ko"]=strings(c.crew_ko);if(!c.crew_roster.empty())v.object["crew_roster"]=strings(c.crew_roster);v.object["fire"]=boolean(c.fire);v.object["ammo_rack_death"]=boolean(c.ammo_rack_death);v.object["events"]=array();return v;}
inline void criticalEvents(Value&v,const std::vector<mechanics::CriticalEvent>&events){auto&out=v.object["events"];out=array();for(const auto&r:events){const auto kind=r.kind==mechanics::CriticalEventKind::device?"device":r.kind==mechanics::CriticalEventKind::crew?"crew":r.kind==mechanics::CriticalEventKind::fire?"fire":"ammo_rack";Value e=event(kind);if(!r.name.empty())e.object["name"]=text(r.name);auto status=[](mechanics::CriticalStatus s){return s==mechanics::CriticalStatus::destroyed?"destroyed":s==mechanics::CriticalStatus::critical?"critical":"normal";};e.object["state"]=r.kind==mechanics::CriticalEventKind::fire?boolean(r.status==mechanics::CriticalStatus::fire_on):text(status(r.status));if(r.kind==mechanics::CriticalEventKind::device)e.object["old_state"]=text(status(r.old_status));e.object["cause"]=text(r.cause);out.array.push_back(std::move(e));}}
inline mechanics::EquipmentEffect equipmentEffect(const Value&contract,const std::string&selected,const mechanics::CombatState&s){mechanics::EquipmentEffect e;const auto kind=field(contract,"kind");e.action=kind=="extinguisher"?mechanics::EquipmentAction::extinguish_fire:kind=="medkit"?mechanics::EquipmentAction::restore_crew:mechanics::EquipmentAction::repair_devices;e.selected=selected;e.all=contract.get("repairAll").truth();e.clear_stun=kind=="medkit"&&s.stun_end_server_time_ms>0;e.stun_base_end_server_time_ms=s.stun_end_server_time_ms;return e;}
}
